import { RichValue } from "@/registry/p1/internal/rich";
import "./rich-text.css";

export interface RichTextProps {
  content: string;
  measure: "narrow" | "standard" | "wide";
  size: "regular" | "large";
  dropCap: "off" | "on";
}

export function RichTextRender({ content, measure, size, dropCap }: RichTextProps) {
  return (
    <div
      className="p1-rich-text p1-block"
      data-measure={measure}
      data-size={size}
      data-dropcap={dropCap}
    >
      <div className="p1-rich-text__inner">
        <RichValue value={content} />
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { RichTextRender, type RichTextProps } from "./rich-text";
export type { RichTextProps };

export const RichTextBlock: ComponentConfig<RichTextProps> = {
  fields: {
    content: { type: "richtext" as const, contentEditable: true, visible: false },
    measure: {
      type: "select" as const,
      options: [
        { label: "Narrow", value: "narrow" },
        { label: "Standard", value: "standard" },
        { label: "Wide", value: "wide" },
      ],
    },
    size: {
      type: "radio" as const,
      options: [
        { label: "Regular", value: "regular" },
        { label: "Large", value: "large" },
      ],
    },
    dropCap: {
      type: "radio" as const,
      options: [
        { label: "Off", value: "off" },
        { label: "On", value: "on" },
      ],
    },
  },
  defaultProps: {
    content:
      "<p>A year ago, shipping a change meant a ticket, a queue, and a wait. Today it takes minutes — and the difference wasn't a single tool.</p>" +
      "<h2>It started with previews</h2>" +
      "<p>Every change got a shareable link before it went live. Reviewers stopped guessing and <mark>started seeing</mark>.</p>" +
      "<ul><li>Fewer round-trips between teams</li><li>Marketers unblocked from engineering</li><li>Confidence to publish on a Friday</li></ul>" +
      "<h3>The habit that stuck</h3>" +
      "<p>We made \"preview first\" the default, not the exception. Small change, large compounding effect.</p>" +
      "<blockquote>The best workflow is the one your whole team actually uses.</blockquote>",
    measure: "standard",
    size: "regular",
    dropCap: "off",
  },
  render: RichTextRender,
};

export const meta = defineMeta({
  title: 'Rich Text',
  description: 'Free-form rich-text editor output with configurable measure, size, and optional drop cap; use for long-form article body content.',
  categories: ["editorial"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-rich"],
});

.p1-rich-text__inner {
  margin-inline: auto;
}

.p1-rich-text[data-measure="narrow"] .p1-rich-text__inner {
  max-inline-size: var(--p1-container-narrow);
}
.p1-rich-text[data-measure="standard"] .p1-rich-text__inner {
  max-inline-size: var(--p1-container-default);
}
.p1-rich-text[data-measure="wide"] .p1-rich-text__inner {
  max-inline-size: var(--p1-container-wide);
}

.p1-rich-text__inner > * { margin-block: 0; }
.p1-rich-text__inner > * + * { margin-block-start: var(--p1-space-md); }

.p1-rich-text__inner p,
.p1-rich-text__inner li {
  line-height: var(--p1-leading-normal);
  text-wrap: pretty;
}
.p1-rich-text[data-size="large"] .p1-rich-text__inner p,
.p1-rich-text[data-size="large"] .p1-rich-text__inner li {
  font-size: var(--p1-text-lg);
}

.p1-rich-text__inner h2 {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  line-height: var(--p1-leading-tight);
  margin-block-start: var(--p1-space-xl);
  text-wrap: balance;
}
.p1-rich-text__inner h3 {
  font-size: var(--p1-text-xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.01em;
  line-height: var(--p1-leading-tight);
  margin-block-start: var(--p1-space-lg);
  text-wrap: balance;
}

.p1-rich-text__inner ul,
.p1-rich-text__inner ol {
  padding-inline-start: 1.5rem;
}
.p1-rich-text__inner ul { list-style-type: disc; }
.p1-rich-text__inner ol { list-style-type: decimal; }
.p1-rich-text__inner li + li { margin-block-start: 0.375rem; }

.p1-rich-text__inner blockquote {
  border-inline-start: 3px solid var(--p1-border);
  color: var(--p1-fg-muted);
  font-style: italic;
  padding-inline-start: var(--p1-space-md);
}

.p1-rich-text__inner strong { font-weight: var(--p1-weight-bold); }
.p1-rich-text__inner em { font-style: italic; }
.p1-rich-text__inner a {
  color: var(--p1-accent);
  text-decoration: underline;
}
.p1-rich-text__inner mark {
  background-color: color-mix(in oklch, var(--p1-warning) 40%, transparent);
  border-radius: 0.125rem;
  padding-inline: 0.125rem;
}

.p1-rich-text[data-dropcap="on"] .p1-rich-text__inner > p:first-of-type::first-letter {
  float: left;
  font-size: 4em;
  font-weight: 800;
  line-height: 0.8;
  margin-block-end: 0.05em;
  margin-inline-end: 0.1em;
}

